function validate([initialEnergy, initialExperience, energy, experience]) {
  const ok = v => Number.isInteger(v) && v >= 1 && v <= 100;
  if (!ok(initialEnergy) || !ok(initialExperience)) return 'initialEnergy and initialExperience are integers from 1 to 100.';
  if (!Array.isArray(energy) || energy.length < 1 || energy.length > 100) return 'There must be 1 to 100 opponents.';
  if (!Array.isArray(experience) || experience.length !== energy.length) return 'energy and experience must have the same length.';
  if (!energy.every(ok) || !experience.every(ok)) return 'Every opponent value is an integer from 1 to 100.';
  return null;
}

