function minNumberOfHours(initialEnergy, initialExperience, energy, experience) {
  let totalEnergy = 0;
  for (const cost of energy) {
    totalEnergy += cost;
  }
  let hours = Math.max(0, totalEnergy + 1 - initialEnergy);

  let current = initialExperience;
  for (let i = 0; i < experience.length; i++) {
    if (current <= experience[i]) {
      const gap = experience[i] + 1 - current;
      hours += gap;
      current += gap;
    }
    current += experience[i];
  }
  return hours;
}

