function minNumberOfHours(initialEnergy, initialExperience, energy, experience) {
  // Simulate the whole competition; raise each starting value one hour at a time until it is enough.
  const beatsAll = (en, ex) => {
    for (let i = 0; i < energy.length; i++) {
      if (en <= energy[i] || ex <= experience[i]) return false;
      en -= energy[i];
      ex += experience[i];
    }
    return true;
  };
  let extraEnergy = 0;
  while (!beatsAll(initialEnergy + extraEnergy, Infinity)) extraEnergy++;
  let extraExperience = 0;
  while (!beatsAll(Infinity, initialExperience + extraExperience)) extraExperience++;
  if (!beatsAll(initialEnergy + extraEnergy, initialExperience + extraExperience)) throw new Error('unexpected');
  return extraEnergy + extraExperience;
}

